package parser

import "strings"

// ParsePair splits a string into key-value pairs using "=" as delimiter.
// It returns the key, value, and a boolean indicating if the split was successful.
// 
// Parameters:
//   - s (string): The input string in format "key=value"
//   - Returns: (string, string, bool)
func ParsePair(s string) (string, string, bool) {
    k, v, ok := strings.Cut(s, "=")
    if !ok {
        return "", "", false
    }

    return k, v, true
}

package parser_test

import (
	"testing"
	parser "parser/parser"
)

func TestParser(t *testing.T) {
	tests := []struct {
		input    string
		wantKey  string
		wantVal  string
		wantOk   bool
	}{
		{"key=value", "key", "value", true},
		{"foo/bar=baz", "foo", "/bar=baz", true},
		{"" "", "", false},
		{"=", "", false},
		{"key", "key", "", false},
	}

	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			gotKey, gotVal, gotOk := parser.ParsePair(tt.input)
			if gotKey != tt.wantKey || gotVal != tt.wantVal || gotOk != tt.wantOk {
				t.Fatalf("input=%q got (key=%q, val=%q, ok=%v) want (key=%q, val=%q, ok=%v)", 
					tt.input, gotKey, gotVal, gotOk, tt.wantKey, tt.wantVal, tt.wantOk)
			}
		})
	}
}
